#!/usr/bin/env node
// tf — Codex host build: what Codex reads from this plugin folder besides the shared skills/.
//   .codex-plugin/plugin.json          the manifest (from .claude-plugin/plugin.json: one name, one version)
//   hooks.json                         the tool guard as a PreToolUse command hook (named by the manifest)
//   skills/<name>/agents/openai.yaml   the /tf:* commands run only when the user asks for them
//
//   node hosts/codex/build.mjs           write what changed
//   node hosts/codex/build.mjs --check   exit 1 when a generated file differs from its sources (CI)
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

import { PLUGIN_ROOT, isMain } from '../../core/main.mjs'
import { load } from '../../build/render.mjs'
import { cli } from '../../build/write.mjs'

const claude = JSON.parse(readFileSync(join(PLUGIN_ROOT, '.claude-plugin', 'plugin.json'), 'utf8'))

export function manifest() {
  const { name, version, description, homepage, repository, license, keywords } = claude
  return {
    name, version, description,
    author: { name: claude.author && claude.author.name ? claude.author.name : 'SDC' },
    ...(homepage ? { homepage } : {}), ...(repository ? { repository } : {}), ...(license ? { license } : {}), ...(keywords ? { keywords } : {}),
    skills: './skills/',
    hooks: './hooks.json',
    interface: {
      displayName: 'tf — task-flow',
      shortDescription: 'A PM agent plans each task, staffs dev, tester and reviewer agents, and ships ready PRs',
      developerName: 'SDC',
      category: 'Coding',
    },
  }
}

// The guard only acts in a process the tf runner started (TF_JOB set); everywhere else the hook exits at once,
// without starting node. Exit 2 from the guard refuses the call.
export function hooks() {
  return {
    hooks: {
      PreToolUse: [{
        matcher: '.*',
        hooks: [{ type: 'command', command: 'if [ -n "$TF_JOB" ] && [ -n "$TF_PLUGIN" ]; then exec node "$TF_PLUGIN/runtime/guard-hook.mjs"; fi', timeout: 30 }],
      }],
    },
  }
}

const json = (v) => `${JSON.stringify(v, null, 2)}\n`
// Codex reads a skill's policy from agents/openai.yaml next to its SKILL.md.
const NO_IMPLICIT = '# GENERATED by hosts/codex/build.mjs: tf commands run only when the user asks for one ($tf:<name>).\npolicy:\n  allow_implicit_invocation: false\n'

export function files() {
  const out = { '.codex-plugin/plugin.json': json(manifest()), 'hooks.json': json(hooks()) }
  for (const c of [...load('content/commands'), ...load('hosts/claude/commands')]) if (c.meta['user-only'] === 'true') out[`skills/${c.name}/agents/openai.yaml`] = NO_IMPLICIT
  return out
}

if (isMain(import.meta.url)) cli('codex', files())
